import android.app.UiAutomation;
import android.os.*;
import android.view.accessibility.AccessibilityNodeInfo;
public final class GpuWifiLayoutProbe {
 static void enabled(String id,boolean expected)throws Exception{AccessibilityNodeInfo n=GpuApiProbe.node(id);GpuUiProbe.check(n.isEnabled()==expected,id+" enabled state");n.recycle();}
 public static void main(String[] args)throws Exception{
  HandlerThread t=new HandlerThread("wifi-layout");t.start();Object c=Class.forName("android.app.UiAutomationConnection").getConstructor().newInstance();UiAutomation a=(UiAutomation)UiAutomation.class.getConstructor(Looper.class,Class.forName("android.app.IUiAutomationConnection")).newInstance(t.getLooper(),c);GpuRadioProbe.automation=a;GpuApiProbe.a=a;GpuWifiLocationProbe.a=a;
  try{UiAutomation.class.getMethod("connect").invoke(a);android.accessibilityservice.AccessibilityServiceInfo i=a.getServiceInfo();i.flags|=android.accessibilityservice.AccessibilityServiceInfo.FLAG_REPORT_VIEW_IDS;a.setServiceInfo(i);Thread.sleep(1000);
   GpuChromeProbe.tab("Home");GpuApiProbe.click("home-appearance-light");GpuUiProbe.waitText("home-appearance-resolved","Light");GpuChromeProbe.tab("API");GpuApiProbe.click("api-wifi");enabled("wifi-start",true);enabled("wifi-stop",false);GpuRadioProbe.screenshot("gpu-wifi-module-light");GpuApiProbe.click("wifi-start");GpuWifiLocationProbe.permission();GpuUiProbe.waitText("wifi-status","Module started");enabled("wifi-start",false);enabled("wifi-stop",true);GpuRadioProbe.screenshot("gpu-wifi-cards-light");
   GpuApiProbe.click("wifi-current");GpuApiProbe.click("wifi-listener-on");GpuUiProbe.waitText("wifi-listener-status","Listening: On");GpuApiProbe.click("wifi-listener-off");GpuUiProbe.waitText("wifi-listener-status","Listening: Off");GpuApiProbe.click("wifi-listener-on");GpuChromeProbe.back();GpuApiProbe.click("api-wifi");GpuUiProbe.waitText("wifi-listener-status","Listening: Off");
   GpuApiProbe.click("wifi-scan");String status="";for(int j=0;j<30;j++){status=GpuApiProbe.text("wifi-status");if(!status.startsWith("Scanning"))break;Thread.sleep(500);}GpuUiProbe.check(!status.startsWith("Scanning")&&!status.isEmpty(),"scan settled");System.out.println("Scan: "+status);GpuApiProbe.node("wifi-scan").recycle();GpuRadioProbe.screenshot("gpu-wifi-scan-light");enabled("wifi-connect",false);if(status.startsWith("Found")&&!status.equals("Found 0 networks")){String name=GpuApiProbe.text("wifi-network-0");GpuApiProbe.click("wifi-network-0");GpuUiProbe.check(GpuApiProbe.text("wifi-ssid").equals(name),"network selection fills SSID");enabled("wifi-connect",true);GpuRadioProbe.screenshot("gpu-wifi-connect-light");}
   GpuChromeProbe.back();GpuChromeProbe.tab("Home");GpuApiProbe.click("home-appearance-dark");GpuUiProbe.waitText("home-appearance-resolved","Dark");GpuChromeProbe.tab("API");GpuApiProbe.click("api-wifi");GpuApiProbe.node("wifi-start").recycle();GpuShareLayoutProbe.themePixel(true);GpuRadioProbe.screenshot("gpu-wifi-cards-dark");GpuApiProbe.click("wifi-stop");GpuUiProbe.waitText("wifi-status","Module stopped");enabled("wifi-start",true);enabled("wifi-stop",false);GpuChromeProbe.back();GpuChromeProbe.tab("Home");GpuApiProbe.click("home-appearance-light");GpuUiProbe.waitText("home-appearance-resolved","Light");System.out.println("PASS WiFi light/dark groups, module start/stop, listener controls and cleanup, current-info and scan result/error");
  }catch(Throwable error){error.printStackTrace();throw error;}finally{UiAutomation.class.getMethod("disconnect").invoke(a);t.quitSafely();}
 }
}
